import {TODAY,uid} from './store.js';
import {dailyCalories,smoothWeight,weightTrend,adaptiveMaintenance,goalTimeline,tdee,rmr,within,addDays,bodyComposition,hrBands,metEnergy} from './science.js';
import {esc,icon,btn,empty,field,select,metric,num,dateLabel,modal,toast,chart} from './ui.js';
import {groups,exercises} from './data.js';
export function overviewView(C){const {state}=C,today=TODAY(),c=state.calories.filter(c=>c.date===today).reduce((a,c)=>a+c.kcal,0),weight=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date)).at(-1),sessions=state.sessions.filter(s=>within(s.date,today,7)),minutes=state.cardio.filter(s=>s.date===today).reduce((a,c)=>a+c.duration,0),weights=state.weights.filter(w=>within(w.date,today,30)),dates=Array.from({length:7},(_,i)=>{const d=new Date(today+'T12:00:00');const dow=(d.getDay()+6)%7;d.setDate(d.getDate()-dow+i);return d.toLocaleDateString('en-CA')}),scheduled=state.schedule.filter(s=>s.date===today),training=scheduled.map(s=>state.routines.find(r=>r.id===s.routineId)).filter(Boolean);return `<div class="page-head"><div><h1>Today</h1><p>${dateLabel(today,{weekday:'long',month:'long',day:'numeric'})}</p></div><div class="button-group">${btn('Log weight','add-weight','','plus')}${btn('Add calories','add-calories','primary','plus')}</div></div>${C.backupNudge()}${state.draft?`<div class="live-banner"><span><strong>${esc(state.draft.name)}</strong> · unfinished workout</span>${btn('Continue','go-training','small primary')}</div>`:''}<div class="metrics">${metric('Calories today',num(c),'kcal',num(Math.abs(state.profile.calorieTarget-c))+' '+(state.profile.calorieTarget-c>=0?'remaining':'over target'),'calories')}${metric('Latest weight',num(C.displayWeight(weight?.kg),1),C.weightUnit(),weight?dateLabel(weight.date):'No weigh-ins yet','weight')}${metric('Training · last 7 days',sessions.length,'sessions',sessions.length?'':'No sessions yet','training')}${metric('Movement today',num(minutes),'min',state.cardio.filter(x=>x.date===today).length+' activities logged','cardio')}</div><div class="grid two lead-side"><div class="stack"><section class="card"><div class="card-head"><h2>Body-weight trend</h2><span class="badge">Last 30 days</span></div>${weights.length?chart(smoothWeight(weights).map(p=>({...p,value:C.displayWeight(p.value)})),{unit:C.weightUnit(),seriesLabel:'7-day mean',secondary:[...weights].sort((a,b)=>a.date.localeCompare(b.date)).map(p=>({date:p.date,value:C.displayWeight(p.kg)}))}):empty('No weigh-ins yet','Log your weight a few times to see a trend.','add-weight','Log a weigh-in')}<details class="fine"><summary>About this</summary><p>The blue line is the trailing 7-day mean of available weigh-ins. Water, glycogen and food mass can move the scale without a change in body fat.</p></details></section><section class="card"><div class="card-head"><h2>This week</h2>${btn('View plan','go-plan','small')}</div><div class="week">${dates.map(d=>{const logged=state.sessions.some(s=>s.date===d),planned=state.schedule.some(s=>s.date===d);return `<div class="day ${d===today?'today':''} ${logged?'logged':''}"><small>${dateLabel(d,{weekday:'short'})}</small><div class="date">${new Date(d+'T12:00:00').getDate()}</div><div class="activity" title="${logged?'Workout logged':planned?'Workout planned':'No workout'}"></div><small>${logged?'Done':planned?'Planned':'—'}</small></div>`}).join('')}</div></section><section class="card"><div class="card-head"><h2>Training balance</h2>${btn('Muscle atlas','go-anatomy','small')}</div>${C.volumeBars(7,6)}</section></div><div class="stack"><section class="card accent-card"><div class="eyebrow">${training.length?'Scheduled today':'Next workout'}</div><h2 style="margin-top:14px;font-size:1.55rem">${training.length?esc(training[0].name):'Nothing scheduled today'}</h2><p>${training.length?training[0].exercises.length+' exercises · targets are editable during your workout.':'Start an empty workout, or set up routines in Plan.'}</p>${training.length?btn('Start this workout','start-routine:'+training[0].id):btn('Start workout','start-workout')}</section><section class="card"><div class="card-head"><h2>Calories today</h2>${btn('View','go-calories','small')}</div><div class="progress"><span style="width:${Math.min(100,c/state.profile.calorieTarget*100)}%"></span></div><p class="meta" style="margin-top:10px">${num(c)} / ${num(state.profile.calorieTarget)} kcal</p>${state.calories.filter(c=>c.date===today).map(c=>`<div class="row"><div><strong>${esc(c.description||'Calorie entry')}</strong><p>${num(c.kcal)} kcal</p></div>${btn('Edit','edit-calories:'+c.id,'small')}</div>`).join('')||empty('Nothing logged yet','Add a calorie total with an optional description.','add-calories','Add calories')}</section></div></div>`}
export function caloriesView(C){const day=C.ui.calorieDate||TODAY(),days=C.ui.caloriePeriod||30,daily=dailyCalories(C.state.calories,C.state.calorieDays,day,days),entries=C.state.calories.filter(x=>x.date===day),total=entries.reduce((a,x)=>a+x.kcal,0),complete=daily.filter(d=>d.complete),avg=complete.length?complete.reduce((a,x)=>a+x.value,0)/complete.length:null;return `<div class="page-head"><div><h1>Calories</h1></div>${btn('Add calories','add-calories','primary','plus')}</div><div class="grid two"><div class="stack"><section class="card"><div class="card-head"><h2>Entries</h2><input class="search day-selector" type="date" name="calorie-date" value="${day}" max="${TODAY()}" aria-label="Date to inspect"></div><div class="metrics summary-metrics"><div><div class="meta">Logged</div><div class="large-number">${num(total)} <small>kcal</small></div></div><div><div class="meta">Target</div><div class="large-number">${num(C.state.profile.calorieTarget)}</div></div><div><div class="meta">${total<=C.state.profile.calorieTarget?'Remaining':'Over target'}</div><div class="large-number">${num(Math.abs(C.state.profile.calorieTarget-total))}</div></div></div><div class="progress"><span style="width:${Math.min(100,total/C.state.profile.calorieTarget*100)}%"></span></div>${entries.length?entries.map(c=>`<div class="row"><div class="entry-description"><strong>${esc(c.description||'Calorie entry')}</strong><p>${num(c.kcal)} kcal</p></div><div class="row-actions">${btn('Edit','edit-calories:'+c.id,'small')}${btn('Delete','delete-calories:'+c.id,'small danger')}</div></div>`).join(''):empty('No entries for this date','An unlogged day is unknown, not zero intake.')}<div style="margin-top:20px">${btn(C.state.calorieDays.includes(day)?'Day marked complete · reopen':'Mark day complete','complete-calories:'+day,C.state.calorieDays.includes(day)?'':'primary')}</div><details class="fine"><summary>About this</summary><p>Mark a day complete only after logging all intake. Complete days are used for intake averages and maintenance calibration. Editing a completed day reopens it.</p></details></section><section class="card"><div class="card-head"><h2>Intake history</h2><div class="button-group">${[7,30,90].map(n=>btn(n===7?'Week':n===30?'Month':'90 days','calorie-period:'+n,'small '+(days===n?'primary':''))).join('')}</div></div>${chart(daily.filter(x=>x.logged||x.complete),{unit:'kcal/day',bars:true})}<details class="fine"><summary>About this</summary><p>Only logged or confirmed complete days are plotted. Partial entries are not a full day's intake.</p></details></section></div><div class="stack"><section class="card"><h2>Daily target</h2><form id="calorie-target-form">${field('target','Calories per day',C.state.profile.calorieTarget,'number','required min="500" max="10000" step="1"')}<button class="btn" type="submit">Update target</button></form>${(()=>{const w=[...C.state.weights].sort((a,b)=>a.date.localeCompare(b.date)).at(-1)?.kg||C.state.profile.weight,e=tdee(C.state.profile,w);return e&&Math.round(e.value)!==C.state.profile.calorieTarget?`<p class="note-box" style="margin-top:16px">Your current maintenance estimate is ${num(e.value)} kcal/day · ${esc(e.method)}.</p>${btn('Use as target','use-maintenance:'+Math.round(e.value),'small')}`:''})()}<details class="fine"><summary>About this</summary><p>A user-chosen target, not a dietary prescription. Calorie needs vary and expenditure estimates are imperfect.</p></details></section><section class="card"><h2>Selected period</h2><div class="row"><span>Complete days</span><strong>${complete.length} / ${days}</strong></div><div class="row"><span>Average complete-day intake</span><strong>${num(avg)} kcal</strong></div><div class="row"><span>Days with any entries</span><strong>${daily.filter(x=>x.logged).length}</strong></div>${btn('Compare with weight','go-insights','small')}</section><section class="card"><h2>Exercise calories</h2><p class="note-box">Exercise energy estimates do not automatically increase your calorie target. An activity-based maintenance estimate already includes typical movement.</p>${C.sourceLinks(['careau2021','compendium_methods2024'])}</section></div></div>`}
export function weightDialog(C,id=''){const w=C.state.weights.find(x=>x.id===id)||{date:TODAY(),kg:'',note:''};modal(id?'Edit weigh-in':'Log a weigh-in',`<div class="form-grid">${field('date','Date',w.date,'date','required max="'+TODAY()+'"')}${field('weight','Weight ('+C.weightUnit()+')',C.displayWeight(w.kg),'number','required min="1" max="1000" step="any"')}<div class="wide">${field('note','Conditions / note · optional',w.note,'text','maxlength="300"')}</div></div><p class="meta">Similar weighing conditions help interpret trends. A single weigh-in cannot measure a change in body fat.</p>`,async fd=>{const kg=C.parseWeight(Number(fd.get('weight'))),date=fd.get('date');if(kg<25||kg>400)throw Error('Enter a weight between 25 and 400 kg (or the equivalent in pounds).');if(C.state.weights.some(x=>x.date===date&&x.id!==id))throw Error('There is already a weigh-in for this date. Edit that entry instead.');const v={id:id||uid(),date,kg,note:fd.get('note').trim()};C.state.weights=id?C.state.weights.map(x=>x.id===id?v:x):[...C.state.weights,v];await C.save('Weigh-in saved')})}
export function bodyView(C){const tab=C.ui.bodyTab||'weight',weights=[...C.state.weights].sort((a,b)=>a.date.localeCompare(b.date)),latest=weights.at(-1),trend=weightTrend(weights,TODAY()),energy=tdee(C.state.profile,latest?.kg||C.state.profile.weight),adaptive=adaptiveMaintenance(C.state,TODAY()),timeline=goalTimeline(weights,C.state.profile.targetWeight,TODAY());return `<div class="page-head"><div><h1>Body</h1></div><div class="button-group">${btn('Add measurement','add-measurement')}${btn('Log weight','add-weight','primary','plus')}</div></div><div class="tabs" role="group" aria-label="Body tracking">${[['weight','Weight trend'],['measurements','Measurements'],['composition','Body composition'],['photos','Progress photos']].map(([id,title])=>`<button aria-pressed="${tab===id}" class="${tab===id?'active':''}" data-action="body-tab:${id}">${title}</button>`).join('')}</div>${tab==='weight'?`<div class="metrics">${metric('Latest weigh-in',num(C.displayWeight(latest?.kg),1),C.weightUnit(),latest?dateLabel(latest.date):'No data yet','weight')}${metric('Recent trend',trend?num(C.displayWeight(trend.weekly),2):'—',C.weightUnit()+'/week',trend?trend.n+' weigh-ins over '+trend.span+' days':'Needs 5 weigh-ins spanning 14 days','insights')}${metric('Resting expenditure',num(energy?.rmr),'kcal/day','Mifflin–St Jeor prediction','body')}${metric('Maintenance estimate',num(adaptive.ready?adaptive.value:energy?.value),'kcal/day',adaptive.ready?'Stable-weight intake heuristic':energy?energy.method:'Complete profile to estimate','calories')}</div><div class="grid two"><div class="stack"><section class="card"><div class="card-head"><h2>Weight history</h2><span class="badge">7-day smoothing</span></div>${chart(smoothWeight(weights).map(p=>({...p,value:C.displayWeight(p.value)})),{unit:C.weightUnit(),seriesLabel:'7-day mean',secondary:weights.map(p=>({date:p.date,value:C.displayWeight(p.kg)}))})}<details class="fine"><summary>About this</summary><p>Blue: trailing 7-day mean of available weigh-ins. Dotted: raw readings. No values are invented on missing days.</p></details></section><section class="card"><h2>Weigh-ins</h2>${weights.length?[...weights].reverse().map(w=>`<div class="row"><div><strong>${num(C.displayWeight(w.kg),1)} ${C.weightUnit()}</strong><p>${dateLabel(w.date)}${w.note?' · '+esc(w.note):''}</p></div><div class="row-actions">${btn('Edit','edit-weight:'+w.id,'small')}${btn('Delete','delete-weight:'+w.id,'small danger')}</div></div>`).join(''):empty('No weigh-ins yet','Start with a measurement under consistent conditions.','add-weight','Log weight')}</section></div><div class="stack"><section class="card"><h2>Energy estimates</h2><p class="note-box">${energy?esc(energy.method):'Add age, height, equation coefficient, and body weight in Settings.'}</p>${energy?`<div class="row"><span>Predicted maintenance</span><strong>${num(energy.value)} kcal/day</strong></div>`:''}<div class="notice"><strong>Adaptive maintenance</strong><p>${adaptive.ready?num(adaptive.value)+' kcal/day from '+adaptive.days+' complete days. ':''}${esc(adaptive.reason)}</p></div><details class="fine"><summary>About this</summary><p>The app recalculates the weight-based estimate as weight changes. It only uses intake as a maintenance anchor when the recent weight trend is approximately stable (within 0.1% of body mass/week). That threshold and the data minimums are app heuristics. No fixed kcal-per-kg conversion is used.</p></details>${C.sourceLinks(['mifflin1990','hall2011'])}</section><section class="card"><h2>Weight goal</h2><p class="note-box">${C.state.profile.targetWeight?'Target: '+num(C.displayWeight(C.state.profile.targetWeight),1)+' '+C.weightUnit():'No target weight set.'}</p>${timeline?.reached?'<div class="notice">Your latest weight is within 0.25 kg of the target.</div>':timeline?.weeks?`<div class="notice"><strong>Recent-pace scenario: ${timeline.range[0]}–${timeline.range[1]} weeks</strong><p>${esc(timeline.method)}</p></div>`:`<p class="note-box">${esc(timeline?.reason||'Set a goal and log a consistent trend to see a short-range scenario.')}</p>`}${btn('Edit goal','go-settings','small')}<details class="fine"><summary>About this</summary><p>Water shifts, adherence and changing expenditure can alter the pace. The app avoids long-range linear weight forecasts.</p></details>${C.sourceLinks(['hall2011'])}</section></div></div>`:tab==='measurements'?measurementsView(C):tab==='composition'?compositionView(C):photosView(C)}`}
function measurementsView(C){const selected=C.ui.measurementMetric||'waist',m=[...C.state.measurements].sort((a,b)=>a.date.localeCompare(b.date));return `<div class="grid equal"><section class="card"><h2>Measurement trend</h2>${select('measurement-metric','Body site',selected,['waist','hips','chest','arm','thigh','neck'].map(s=>[s,s[0].toUpperCase()+s.slice(1)]))}${chart(m.filter(x=>x[selected]>0).map(x=>({date:x.date,value:C.displayLength(x[selected])})),{unit:selected+' ('+C.lengthUnit()+')'})}<details class="fine"><summary>About this</summary><p>Use the same tape location, posture and tension each time. Changes reflect measurement variability as well as body changes.</p></details></section><section class="card"><div class="card-head"><h2>Measurement history</h2>${btn('Add','add-measurement','small','plus')}</div>${m.length?[...m].reverse().map(x=>`<div class="row"><div><strong>${dateLabel(x.date)}</strong><p>${['waist','hips','chest','arm','thigh','neck'].filter(s=>x[s]).map(s=>s+': '+num(C.displayLength(x[s]),1)+' '+C.lengthUnit()).join(' · ')}</p><p>${esc(x.note||'')}</p></div><div class="row-actions">${btn('Edit','edit-measurement:'+x.id,'small')}${btn('Delete','delete-measurement:'+x.id,'small danger')}</div></div>`).join(''):empty('No measurements yet','Every field is optional.')}</section></div>`}
export function measurementDialog(C,id=''){const m=C.state.measurements.find(x=>x.id===id)||{date:TODAY(),note:''};modal('Body measurements',`${field('date','Date',m.date,'date','required max="'+TODAY()+'"')}<div class="form-grid">${['waist','hips','chest','arm','thigh','neck'].map(s=>field(s,s[0].toUpperCase()+s.slice(1)+' ('+C.lengthUnit()+')',m[s]?C.displayLength(m[s]):'','number','min="1" max="500" step="any"')).join('')}</div>${field('note','Measurement sites / side / conditions',m.note,'text','maxlength="500"')}`,async fd=>{const v={id:id||uid(),date:fd.get('date'),note:fd.get('note').trim()};for(const key of ['waist','hips','chest','arm','thigh','neck'])v[key]=fd.get(key)?C.parseLength(Number(fd.get(key))):null;if(!['waist','hips','chest','arm','thigh','neck'].some(s=>v[s]))throw Error('Enter at least one measurement.');C.state.measurements=id?C.state.measurements.map(x=>x.id===id?v:x):[...C.state.measurements,v];await C.save('Measurements saved')})}
function compositionView(C){const b=[...C.state.bodyfat].sort((a,b)=>a.date.localeCompare(b.date)),last=b.at(-1),w=last?[...C.state.weights].filter(w=>Math.abs(Date.parse(w.date)-Date.parse(last.date))<=7*86400000).sort((a,b)=>Math.abs(Date.parse(a.date)-Date.parse(last.date))-Math.abs(Date.parse(b.date)-Date.parse(last.date)))[0]:null,composition=w&&last?bodyComposition(w.kg,last.percentage):null;return `<div class="grid equal"><section class="card"><div class="card-head"><h2>Body-fat readings</h2>${btn('Add reading','add-bodyfat','small','plus')}</div>${chart(b.map(x=>({date:x.date,value:x.percentage})),{unit:'Body fat (%)'})}<details class="fine"><summary>About this</summary><p>Methods are not interchangeable. A line across different methods is a record of readings, not proof of true tissue change.</p></details>${b.slice().reverse().map(x=>`<div class="row"><div><strong>${num(x.percentage,1)}% ${x.uncertainty?'± '+num(x.uncertainty,1)+' percentage points':''}</strong><p>${dateLabel(x.date)} · ${esc(x.method)}${x.note?' · '+esc(x.note):''}</p></div><div class="row-actions">${btn('Edit','edit-bodyfat:'+x.id,'small')}${btn('Delete','delete-bodyfat:'+x.id,'small danger')}</div></div>`).join('')}</section><section class="card"><h2>Composition estimates</h2>${composition?`<div class="row"><span>Estimated fat mass</span><strong>${num(C.displayWeight(composition.fat),1)} ${C.weightUnit()}</strong></div><div class="row"><span>Estimated non-fat mass</span><strong>${num(C.displayWeight(composition.lean),1)} ${C.weightUnit()}</strong></div><p class="note-box">Calculated from ${num(last.percentage,1)}% (${esc(last.method)}, ${dateLabel(last.date)}) and ${num(C.displayWeight(w.kg),1)} ${C.weightUnit()} (${dateLabel(w.date)}). Non-fat mass includes more than muscle.</p>${last.uncertainty?`<p class="note-box">The entered percentage uncertainty corresponds to roughly ± ${num(C.displayWeight(w.kg*last.uncertainty/100),1)} ${C.weightUnit()} in these estimates; weight error is additional.</p>`:'<p class="note-box">No uncertainty was supplied. These values must not be interpreted as exact.</p>'}`:empty('Not enough data yet','Add a body-fat reading and a weigh-in within 7 days to derive approximate fat and non-fat mass.')}<div class="notice">Scale-based body-fat readings can differ substantially from reference methods. Keep the measurement method and conditions visible.</div><details class="fine"><summary>About this</summary><p>The app does not estimate body fat from a photograph or assign a health score.</p></details>${C.sourceLinks(['smartscales2021','deurenberg1991'])}</section></div>`}
export function bodyfatDialog(C,id=''){const b=C.state.bodyfat.find(x=>x.id===id)||{date:TODAY(),method:'Bioimpedance scale'};modal('Body-fat reading',`<div class="form-grid">${field('date','Date',b.date,'date','required max="'+TODAY()+'"')}${field('percentage','Body fat (%)',b.percentage,'number','required min="1" max="74" step="any"')}${select('method','Measurement method',b.method,['Bioimpedance scale','DXA','Skinfold calipers','Circumference estimate','Other / manual'])}${field('uncertainty','Known uncertainty · percentage points',b.uncertainty,'number','min="0" max="30" step="any"','','')}<div class="wide">${field('note','Device / protocol / uncertainty source',b.note,'text','maxlength="500"')}</div></div><p class="meta">Leave uncertainty empty if unknown. A device displaying decimals does not establish that level of accuracy.</p>`,async fd=>{const v={id:id||uid(),date:fd.get('date'),percentage:Number(fd.get('percentage')),method:fd.get('method'),uncertainty:fd.get('uncertainty')?Number(fd.get('uncertainty')):null,note:fd.get('note').trim()};C.state.bodyfat=id?C.state.bodyfat.map(x=>x.id===id?v:x):[...C.state.bodyfat,v];await C.save('Body-fat reading saved')})}
function photosView(C){return `<section class="card"><div class="card-head"><h2>Progress photos</h2>${btn('Add photo','add-photo','primary','plus')}</div><p class="note-box">Photos stay in the local journal and are included in backups. Consistent lighting and pose improve comparison; photos do not measure body fat.</p>${C.state.photos.length?`<div class="photo-grid">${[...C.state.photos].sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<figure><img src="${p.data}" alt="${esc(p.caption||'Progress photo from '+p.date)}" loading="lazy"><figcaption><strong>${dateLabel(p.date)}</strong><p>${esc(p.caption||'')}</p>${btn('Delete','delete-photo:'+p.id,'small danger')}</figcaption></figure>`).join('')}</div>`:empty('No photos yet','Add front, side or back photos. They stay on this device.')}</section>`}
export function photoDialog(C){modal('Add a progress photo',`${field('date','Date',TODAY(),'date','required max="'+TODAY()+'"')}<div class="field"><label for="photo-file">Photo</label><input id="photo-file" name="photo" type="file" accept="image/jpeg,image/png,image/webp" required><small>JPEG, PNG or WebP, up to 10 MB. Stored as a resized JPEG up to 1,200 pixels; metadata is removed.</small></div>${field('caption','View / note', '', 'text','maxlength="300"')}`,async fd=>{const f=fd.get('photo');if(!f||!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024)throw Error('Choose a JPEG, PNG or WebP under 10 MB.');const image=await createImageBitmap(f),scale=Math.min(1,1200/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const cx=canvas.getContext('2d');cx.fillStyle='white';cx.fillRect(0,0,canvas.width,canvas.height);cx.drawImage(image,0,0,canvas.width,canvas.height);image.close();C.state.photos.push({id:uid(),date:fd.get('date'),caption:fd.get('caption').trim(),data:canvas.toDataURL('image/jpeg',.85)});await C.save('Photo saved locally')})}
export function cardioView(C){const recent=C.state.cardio.filter(c=>within(c.date,TODAY(),7)),equivalent=recent.reduce((a,c)=>a+c.duration*(c.intensity==='vigorous'?2:c.intensity==='moderate'?1:0),0),bands=hrBands(C.state.profile.age,C.state.profile.hrmax),activity=[...C.state.cardio].sort((a,b)=>b.date.localeCompare(a.date)),wellbeing=[...C.state.wellbeing].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="page-head"><div><h1>Cardio</h1></div><div class="button-group">${C.state.profile.trackWellbeing?btn('Log recovery','add-wellbeing'):''}${btn('Log activity','add-cardio','primary','plus')}</div></div><div class="metrics">${metric('Activity · last 7 days',num(recent.reduce((a,c)=>a+c.duration,0)),'min',recent.length+' recorded activities','cardio')}${metric('Moderate equivalent',num(equivalent),'min/week','Moderate + 2 × vigorous minutes','time')}${metric('Steps today',num(C.state.wellbeing.find(x=>x.date===TODAY())?.steps),'steps','Manual daily total','body')}${metric('Sleep · latest',num(wellbeing.find(x=>x.sleep!==null)?.sleep,1),'hours',wellbeing.find(x=>x.sleep!==null)?.date||'Not logged','moon')}</div><div class="grid two"><div class="stack"><section class="card"><div class="card-head"><h2>Activity history</h2></div>${activity.length?activity.map(c=>{const weight=C.weightAt(c.date),energy=c.met?metEnergy(c.met,weight,c.duration):null;return `<div class="row"><div><strong>${esc(c.type)} · ${num(c.duration)} min</strong><p>${dateLabel(c.date)} · ${esc(c.intensity)}${c.distance?(d=>' · '+num(d,2)+' '+C.distUnit()+' · '+num(d/(c.duration/60),1)+' '+(C.distUnit()==='mi'?'mph':'km/h')+' · '+num(c.duration/d,2)+' min/'+C.distUnit())(C.displayDist(c.distance)):''}${c.hr?' · '+c.hr+' bpm avg':''}</p>${energy?`<p>Estimated energy: ${num(energy.gross)} kcal gross / ${num(energy.net)} above standard rest · ${c.met} MET · ${num(C.displayWeight(weight),1)} ${C.weightUnit()}</p>`:''}<p>${esc(c.note||'')}</p></div><div class="row-actions">${btn('Edit','edit-cardio:'+c.id,'small')}${btn('Delete','delete-cardio:'+c.id,'small danger')}</div></div>`}).join(''):empty('No activities yet','Log a walk, run, ride or anything else.','add-cardio','Log activity')}<details class="fine"><summary>About this</summary><p>Each activity should be a distinct session. Avoid recording an overlapping session twice. Exercise energy is displayed separately and never added to your daily target. ${C.sourceLinks(['compendium_methods2024','careau2021'])}</p></details></section>${C.state.profile.trackWellbeing?`<section class="card"><h2>Recovery journal</h2>${wellbeing.length?wellbeing.map(w=>`<div class="row"><div><strong>${dateLabel(w.date)}</strong><p>${[['sleep','h sleep'],['steps','steps'],['energy','/5 energy'],['soreness','/5 soreness'],['recovery','/5 perceived recovery']].filter(([k])=>w[k]!==null&&w[k]!==undefined).map(([k,u])=>num(w[k],1)+' '+u).join(' · ')}</p><p>${esc(w.note||'')}</p></div><div class="row-actions">${btn('Edit','edit-wellbeing:'+w.id,'small')}${btn('Delete','delete-wellbeing:'+w.id,'small danger')}</div></div>`).join(''):empty('No recovery logs yet','Sleep, steps, energy and soreness are all optional.')}</section>`:''}</div><div class="stack"><section class="card"><h2>Weekly activity</h2><div class="large-number">${num(equivalent)} <small>/ ${C.state.profile.activityGoal||150} min</small></div><div class="progress" style="margin:16px 0"><span style="width:${Math.min(100,equivalent/(C.state.profile.activityGoal||150)*100)}%"></span></div><p class="note-box">WHO recommends 150–300 minutes of moderate aerobic activity or 75–150 minutes of vigorous activity weekly for adults, plus muscle strengthening on at least two days. Some activity is better than none.</p>${C.sourceLinks(['who2020'])}</section><section class="card"><h2>Heart-rate guide</h2>${bands?`<div class="row"><span>Estimated / supplied maximum</span><strong>${num(bands.max)} bpm</strong></div><div class="row"><span>Moderate · 50–70%</span><strong>${bands.moderate.join('–')} bpm</strong></div><div class="row"><span>Vigorous · 70–85%</span><strong>${bands.vigorous.join('–')} bpm</strong></div><details class="fine"><summary>About this</summary><p>${esc(bands.method)}. Age-based HRmax can differ substantially from your actual maximum. These bands do not measure physiological thresholds.</p></details>`:'<p class="note-box">Add age or a known HRmax in Settings to see approximate percent-of-maximum bands.</p>'}<p class="note-box">Talk test: moderate effort generally allows talking but not singing; vigorous effort usually allows only a few words before a breath. Medication can change heart-rate response.</p>${C.sourceLinks(['tanaka2001','aha_hr2024','cdc_intensity2025'])}</section><section class="card"><h2>Sleep in context</h2><p class="note-box">The AASM/SRS consensus recommends adults regularly obtain at least 7 hours of sleep. Your recorded duration is one observation; sleep quality and personal needs also matter.</p>${C.sourceLinks(['aasm_sleep2015'])}</section></div></div>`}
export function cardioDialog(C,id=''){const c=C.state.cardio.find(x=>x.id===id)||{date:TODAY(),type:'Walking',intensity:'moderate',met:null},metOptions=[['','No energy estimate'],...C.evidence.activityMetExamples.map(e=>[String(e.met),e.label+' · '+e.met+' MET']),['custom','Custom MET value']];const d=modal(id?'Edit activity':'Log an activity',`<div class="form-grid">${field('date','Date',c.date,'date','required max="'+TODAY()+'"')}${select('type','Activity',c.type,['Walking','Running','Cycling','Rowing','Swimming','Hiking','Other'])}${field('duration','Duration (minutes)',c.duration,'number','required min="1" max="1440" step="1"')}${field('distance','Distance ('+C.distUnit()+') · optional',c.distance?Number(C.displayDist(c.distance).toFixed(2)):c.distance,'number','min="0" max="1000" step=".01"')}${select('intensity','Intensity · talk-test judgment',c.intensity,[['light','Light'],['moderate','Moderate'],['vigorous','Vigorous']])}${field('hr','Average heart rate (bpm) · optional',c.hr,'number','min="30" max="250" step="1"')}<div class="wide">${select('metPreset','Energy reference · match the actual activity',c.met?(C.evidence.activityMetExamples.some(e=>e.met===c.met)?String(c.met):'custom'):'',metOptions)}${field('met','MET · optional custom value',c.met,'number','min="1" max="25" step="any"')}${field('note','Notes / MET source if custom',c.note,'text','maxlength="500"')}</div></div><p class="meta">MET energy is an approximate reference value, not measured expenditure. Select a pace only when it matches the session. No automatic calorie adjustment.</p>`,async fd=>{const v={id:id||uid(),date:fd.get('date'),type:fd.get('type'),duration:Number(fd.get('duration')),distance:fd.get('distance')?(c.distance&&Number(fd.get('distance'))===Number(C.displayDist(c.distance).toFixed(2))?c.distance:C.parseDist(Number(fd.get('distance')))):null,intensity:fd.get('intensity'),hr:fd.get('hr')?Number(fd.get('hr')):null,met:fd.get('metPreset')===''?null:fd.get('metPreset')==='custom'?(fd.get('met')?Number(fd.get('met')):null):Number(fd.get('metPreset')),note:fd.get('note').trim()};if(fd.get('metPreset')==='custom'&&!v.met)throw Error('Enter a MET value or choose no estimate.');C.state.cardio=id?C.state.cardio.map(x=>x.id===id?v:x):[...C.state.cardio,v];await C.save('Activity saved')});d.querySelector('[name=metPreset]').onchange=e=>{const input=d.querySelector('[name=met]');if(e.target.value!=='custom')input.value=e.target.value}}
export function wellbeingDialog(C,id=''){const w=C.state.wellbeing.find(x=>x.id===id)||{date:TODAY()};modal('Recovery & movement log',`${field('date','Date',w.date,'date','required max="'+TODAY()+'"')}<div class="form-grid">${field('sleep','Sleep (hours) · optional',w.sleep,'number','min="0" max="24" step="any"')}${field('steps','Steps · optional',w.steps,'number','min="0" max="200000" step="1"')}${['energy','soreness','recovery'].map(s=>select(s,s==='recovery'?'Perceived recovery':s[0].toUpperCase()+s.slice(1),String(w[s]??''),[['','Not tracked'],['1','1 · '+(s==='soreness'?'None / very mild':'Very low')],['2','2'],['3','3 · Moderate'],['4','4'],['5','5 · '+(s==='soreness'?'Very high':'Very high')]])).join('')}</div>${field('note','Notes',w.note,'text','maxlength="500"')}<p class="meta">These are personal observations. The app does not diagnose recovery or combine them into a medical score.</p>`,async fd=>{const v={id:id||uid(),date:fd.get('date'),note:fd.get('note').trim()};for(const k of ['sleep','steps','energy','soreness','recovery'])v[k]=fd.get(k)!==''?Number(fd.get(k)):null;if(!['sleep','steps','energy','soreness','recovery'].some(k=>v[k]!==null)&&!v.note)throw Error('Enter an observation or a note.');if(C.state.wellbeing.some(x=>x.date===v.date&&x.id!==id))throw Error('A log exists for this date. Edit it instead.');C.state.wellbeing=id?C.state.wellbeing.map(x=>x.id===id?v:x):[...C.state.wellbeing,v];await C.save('Recovery log saved')})}
export async function journalAction(a,id,C){const map={'add-weight':()=>weightDialog(C),'edit-weight':()=>weightDialog(C,id),'add-measurement':()=>measurementDialog(C),'edit-measurement':()=>measurementDialog(C,id),'add-bodyfat':()=>bodyfatDialog(C),'edit-bodyfat':()=>bodyfatDialog(C,id),'add-photo':()=>photoDialog(C),'add-cardio':()=>cardioDialog(C),'edit-cardio':()=>cardioDialog(C,id),'add-wellbeing':()=>wellbeingDialog(C),'edit-wellbeing':()=>wellbeingDialog(C,id)};if(map[a]){map[a]();return true}if(a==='use-maintenance'){C.state.profile.calorieTarget=Number(id);await C.save('Daily target updated');return true}if(a==='body-tab'){C.ui.bodyTab=id;C.render();return true}if(a==='calorie-period'){C.ui.caloriePeriod=Number(id);C.render();return true}if(a==='complete-calories'){C.state.calorieDays=C.state.calorieDays.includes(id)?C.state.calorieDays.filter(x=>x!==id):[...C.state.calorieDays,id];await C.save('Day status updated');return true}const collection={'delete-weight':'weights','delete-measurement':'measurements','delete-bodyfat':'bodyfat','delete-photo':'photos','delete-cardio':'cardio','delete-wellbeing':'wellbeing','delete-calories':'calories'}[a];if(collection){C.confirm('Delete this entry?','This removes the record and updates the related charts.',async()=>{const old=C.state[collection].find(x=>x.id===id);C.state[collection]=C.state[collection].filter(x=>x.id!==id);if(collection==='calories')C.state.calorieDays=C.state.calorieDays.filter(d=>d!==old.date);await C.save('Entry deleted')});return true}return false}
